if(!meta.equipment)meta.equipment=defaultMeta().equipment;if(!Array.isArray(meta.inventory))meta.inventory=[];if(!Array.isArray(meta.stash))meta.stash=[];if(!meta.callsign)meta.callsign=`P-${Math.floor(1000+Math.random()*9000)}`;
