function migrateAmmoEconomy(){if(meta.ammoEconomyV1)return;const items=[meta.equipment?.primary,meta.equipment?.secondary,...(meta.inventory||[]),...(meta.stash||[])].filter(Boolean),bonus=[];for(const it of items){if(it.kind==='weapon'){it.ammoTier=it.ammoTier||1;if((it.reserve||0)>0){bonus.push(makeAmmo(WEAPONS[it.type]?.caliber||'9mm',1,it.reserve));it.reserve=0}}else if(it.kind==='ammo'){it.caliber=it.caliber||WEAPONS[it.type]?.caliber||'9mm';it.tier=Math.max(1,Math.min(5,Number(it.tier)||1));it.qty=Math.max(0,Number(it.qty)||0);it.name=`${AMMO_CALIBERS[it.caliber]?.name||it.caliber} T${it.tier} 탄약`;it.value=it.value??ammoPrice(it.caliber,it.tier,it.qty)}}meta.stash.push(...bonus);meta.ammoEconomyV1=true;save()}
