 const stash=$('#stashList');stash.innerHTML='';if(!meta.stash.length)stash.innerHTML='<div class="muted">창고가 비어 있습니다.</div>';meta.stash.forEach((it,i)=>{const d=document.createElement('div');d.className='stashItem';const price=sellPrice(it),ri=repairInfo(it);d.innerHTML=`<b>${itemName(it)}</b><div class="meta">${itemMeta(it)}<br>평가 ${money(it.value||0)} · 판매 ${money(price)}${ri&&ri.missing>0?` · 수리비 ${money(ri.cost)}`:''}</div>`;const actions=document.createElement('div');actions.className='stashActions';const b=document.createElement('button');b.textContent='출격 인벤토리로';b.disabled=!canMetaReceive(meta.inventory,it,12);b.onclick=()=>stashToInventory(i);actions.appendChild(b);addRepair(actions,it);const sell=document.createElement('button');sell.className='sellBtn';sell.textContent=price>0?'판매':'판매 불가';sell.disabled=price<=0;sell.onclick=()=>sellFromStash(i);actions.appendChild(sell);d.appendChild(actions);stash.appendChild(d)});
