function currentPlayer(){return snap?.player}
function syncRenderActors(s){const seen=new Set();for(const a of s.actors||[]){seen.add(a.id);let r=renderActors.get(a.id);if(!r){r={x:a.x,y:a.y,angle:a.angle,tx:a.x,ty:a.y,ta:a.angle};renderActors.set(a.id,r)}r.tx=a.x;r.ty=a.y;r.ta=a.angle}for(const id of [...renderActors.keys()])if(!seen.has(id))renderActors.delete(id)}
function processSnapshot(s){const nextReload=s.player?.reload||0,nextWeapon=s.player?.weapon?.type||null;if(nextReload>0&&(lastReloadValue<=0||nextWeapon!==lastReloadWeapon))reloadSound(nextWeapon);lastReloadValue=nextReload;lastReloadWeapon=nextWeapon;snap=s;lastSnapshotAt=performance.now();syncRenderActors(s);if(s.room)roomState=s.room;if(s.openContainer&&document.pointerLockElement===canvas)document.exitPointerLock?.();const now=performance.now();if(now-lastHudAt>=90||s.result||s.openContainer||nextReload>0){lastHudAt=now;renderHUD()}if(s.result&&!lastResultHandled)handleResult(s.result)}
function enterRaid(activeSession){meta.equipment={primary:null,secondary:null,armor:null,helmet:null,backpack:null};meta.inventory=[];save();renderLobby();$('#lobby').classList.add('hidden');$('#raid').classList.remove('hidden');$('#raid').classList.remove('mobileBagOpen');lastResultHandled=false;killFeed=[];soundMarks=[];fx=[];actorHitFlash.clear();renderActors.clear();hurtFlashT=0;lastReloadValue=0;lastReloadWeapon=null;hudBagKey='';hudEqKey='';hudLootKey='';input=emptyInput();session=activeSession;canvas.focus()}
function startRaid(){if(!meta.equipment.primary)return;ensureAudio();const departure={name:meta.callsign||'PLAYER',equipment:cp(meta.equipment),inventory:cp(meta.inventory),visionLevel:meta.visionLevel};if(LOCAL_MODE||multiplayerFallback||!realtime?.connected){const local=new LocalSession(departure);local.on('snapshot',processSnapshot);local.on('event',handleEvent);enterRaid(local);return}if(roomState?.joinable===false)return alert(roomState?.entryClosed?'현재 RAID는 종료 1분 전이라 신규 참가가 마감되었습니다. 다음 RAID를 기다려주세요.':'현재 RAID가 8명으로 가득 찼습니다.');pendingDeparture=departure;$('#raidBtn').disabled=true;$('#roomStateText').textContent='현재 RAID 참가 요청 중...';realtime.join(departure)}
$('#raidBtn').onclick=startRaid;
function handleResult(r){lastResultHandled=true;if(document.pointerLockElement)document.exitPointerLock?.();input.shoot=false;keys.clear();if(session===realtime)realtime.leave();else session?.close();session=null;if(r.status==='extracted'){meta.equipment=r.equipment||{primary:null,secondary:null,armor:null,helmet:null,backpack:null};const cap=12,items=compactMetaAmmo(r.items||[]);meta.inventory=items.slice(0,cap);for(const it of items.slice(cap))addMetaItemStacked(meta.stash,it);save()}showResult(r.status==='extracted',r)}
function showResult(ok,r){const p=$('#resultPanel');p.classList.remove('hidden');p.innerHTML=`<div class="resultCard"><h2 class="${ok?'success':'failed'}">${ok?'EXTRACTED':'RAID LOST'}</h2><p>${ok?`탈출 성공 · ${r.reason}`:`${r.reason} · 출격 장비와 전리품 상실`}</p><p>처치 ${r.kills||0} · 회수품 평가 ${money(r.lootValue||0)} · 자동 현금화 없음</p><button id="backLobby" class="primary">로비로 돌아가기</button></div>`;$('#backLobby').onclick=()=>{p.classList.add('hidden');$('#raid').classList.add('hidden');$('#lobby').classList.remove('hidden');snap=null;ensureBasicPistol();renderLobby()}}
$('#abandonBtn').onclick=()=>{if(!session)return;if(confirm('출격 장비와 전리품을 모두 포기할까요?')){if(document.pointerLockElement)document.exitPointerLock?.();input.shoot=false;keys.clear();if(session===realtime)realtime.leave();else session.close();session=null;lastResultHandled=true;$('#raid').classList.add('hidden');$('#lobby').classList.remove('hidden');snap=null;ensureBasicPistol();renderLobby()}};

function renderRoomStatus(){
 const raidBtn=$('#raidBtn');
 if(LOCAL_MODE||multiplayerFallback){
   $('#roomIdText').textContent=LOCAL_MODE?'LOCAL':'LOCAL FALLBACK';$('#roomMap').textContent=snap?.map?.name||'로컬 순환맵';$('#roomHumans').textContent='1 / 1';$('#roomAi').textContent=snap?.aliveAI??7;$('#roomTime').textContent='--:--';
   const st=$('#roomStateText');st.className='roomState';st.textContent=LOCAL_MODE?'로컬 테스트 모드':'멀티 서버 연결 대기 중 · 현재는 로컬 출격 가능';raidBtn.textContent='현재 RAID 참가';if(!session)raidBtn.disabled=!meta.equipment.primary;return
 }
 const r=roomState;if(!r){$('#roomStateText').textContent=realtime?.connected?'방 정보 수신 중...':'멀티 서버 연결 중...';return}
 const left=Math.max(0,(r.endsAt-Date.now())/1000),m=Math.floor(left/60),sec=Math.floor(left%60),timeText=`${String(m).padStart(2,'0')}:${String(sec).padStart(2,'0')}`,entryClosed=r.entryClosed===true||left<=60;
 $('#roomIdText').textContent=r.roomId;$('#roomMap').textContent=r.mapName||'-';$('#roomHumans').textContent=`${r.humans} / ${r.capacity}`;$('#roomAi').textContent=r.ai;$('#roomTime').textContent=timeText;
 const st=$('#roomStateText');
 if(entryClosed){st.className='roomState full';st.textContent=`신규 참가 마감 · 다음 RAID ${timeText} 후 시작`;raidBtn.textContent='신규 참가 마감';if(!session)raidBtn.disabled=true;return}
 if(!r.joinable){st.className='roomState full';st.textContent='현재 방 FULL · 자리가 비면 참가 가능합니다.';raidBtn.textContent='현재 RAID FULL';if(!session)raidBtn.disabled=true;return}
 st.className='roomState live';st.textContent='중간 참가 가능 · 빈 인간 슬롯은 AI가 보충합니다.';raidBtn.textContent='현재 RAID 참가';if(!session)raidBtn.disabled=!meta.equipment.primary
}
function setupRealtime(){if(LOCAL_MODE){multiplayerFallback=true;$('#netText').textContent='LOCAL TEST MODE';return}realtime=new WebSocketSession(WS_URL);const fallbackTimer=setTimeout(()=>{if(!multiplayerAvailable&&!session){multiplayerFallback=true;$('#netText').textContent='MULTIPLAYER OFFLINE · LOCAL';renderRoomStatus();renderLobby()}},2500);realtime.on('connection',x=>{if(x.connected){clearTimeout(fallbackTimer);multiplayerAvailable=true;multiplayerFallback=false;$('#netText').textContent='MULTIPLAYER CONNECTED'}else{$('#netText').textContent=multiplayerFallback?'MULTIPLAYER OFFLINE · LOCAL':'MULTIPLAYER RECONNECTING'}renderRoomStatus();renderLobby()});realtime.on('status',r=>{roomState=r;multiplayerAvailable=true;multiplayerFallback=false;renderRoomStatus();renderLobby()});realtime.on('joined',()=>{if(!pendingDeparture)return;pendingDeparture=null;enterRaid(realtime)});realtime.on('join_denied',m=>{pendingDeparture=null;alert(m.reason||'현재 RAID에 참가할 수 없습니다.');renderLobby();renderRoomStatus()});realtime.on('snapshot',s=>{if(session===realtime)processSnapshot(s)});realtime.on('event',e=>{if(session===realtime)handleEvent(e)});realtime.on('disconnect',()=>{if(session===realtime&&!lastResultHandled){lastResultHandled=true;session=null;if(document.pointerLockElement)document.exitPointerLock?.();showResult(false,{reason:'멀티 서버 연결 끊김',kills:snap?.player?.kills||0,lootValue:0})}})}
setInterval(renderRoomStatus,250);

function eventOnScreen(e){if(!snap?.player)return false;return Math.hypot(e.x-snap.player.x,e.y-snap.player.y)<1000}
function handleEvent(e){
 if(e.type==='shot'){if(eventOnScreen(e)){const self=e.actor===snap?.playerId,visible=self||snap?.actors?.some(a=>a.id===e.actor);shotSound(e.weapon,self?1:.42);if(visible){const ang=e.angle??0;fx.push({kind:'muzzle',x:e.x+Math.cos(ang)*25,y:e.y+Math.sin(ang)*25,angle:ang,self,t:self?0.115:0.095,max:self?0.115:0.095});}if(self){recoilKick=Math.min(11,recoilKick+(e.recoil||2)*1.35);shake=Math.max(shake,(e.recoil||2)*.7);fx.push({kind:'casing',x:e.x,y:e.y,vx:(Math.random()-.5)*80,vy:-40-Math.random()*45,t:.5,max:.5})}}}
 if(e.type==='impact'&&eventOnScreen(e))fx.push({kind:'impact',x:e.x,y:e.y,t:.18,max:.18});
 if(e.type==='explosion'){if(eventOnScreen(e)){explosionSound(.8);shake=Math.max(shake,10);for(let i=0;i<16;i++)fx.push({kind:'spark',x:e.x,y:e.y,vx:(Math.random()-.5)*380,vy:(Math.random()-.5)*380,t:.45,max:.45})}}
 if(e.type==='hit'){actorHitFlash.set(e.target,{t:.16,max:.16,headshot:!!e.headshot});const ra=renderActors.get(e.target);if(ra&&e.target!==snap?.playerId)fx.push({kind:'damage',x:ra.x,y:ra.y-23,text:`-${e.damage||0}`,t:.55,max:.55});if(e.source===snap?.playerId){hitMarkerT=.16;hitHead=!!e.headshot;shake=Math.max(shake,e.headshot?3:1.5)}if(e.target===snap?.playerId){hurtFlashT=.24;shake=Math.max(shake,7)}}
 if(e.type==='kill'){killFeed.unshift(`${e.killer}  ▸  ${e.victim}`);killFeed=killFeed.slice(0,5);renderKillFeed()}
 if(e.type==='self_step')footstepSound(!!e.loud,e.loud?1:.72);if(e.type==='heard'){const life=e.kind==='footstep'?0.95:e.kind==='gunshot'?1.45:e.kind==='explosion'?1.7:1.1;if(e.kind==='footstep')footstepSound(!!e.loud,e.intensity==='near'?.72:e.intensity==='mid'?.48:.28);soundMarks.push({angle:e.angle,kind:e.kind||'sound',loud:!!e.loud,intensity:e.intensity||'mid',t:life,max:life});if(soundMarks.length>18)soundMarks.splice(0,soundMarks.length-18)}
 if(e.type==='loot')toast(`획득: ${e.item}`);if(e.type==='discard')toast(`버림: ${e.item}`);if(e.type==='equip')toast(`장착: ${e.item}`);if(e.type==='door')toast(`${e.name} ${e.open?'열림':'닫힘'}`);if(e.type==='door_blocked')toast(`${e.name} · 사람이 있어 닫을 수 없음`);if(e.type==='heal_start'&&e.actor===snap?.playerId)toast('치료 시작 · 2초');if(e.type==='heal'&&e.actor===snap?.playerId)toast(`치료 완료 +${e.amount||0} HP`);
}
function renderKillFeed(){$('#killFeed').innerHTML=killFeed.map(x=>`<div class="killMsg">${x}</div>`).join('')}
function toast(t){const el=$('#interactHint'),old=el.textContent;el.textContent=t;clearTimeout(toast.t);toast.t=setTimeout(()=>el.textContent=old,1000)}

function itemSub(it){return itemMeta(it)}
function renderHUD(){if(!snap?.player)return;const p=snap.player;$('#hpText').textContent=Math.ceil(p.hp);$('#hpBar').style.width=`${Math.max(0,p.hp/p.maxHp*100)}%`;$('#armorText').textContent=Math.ceil(p.armor);$('#armorBar').style.width=`${Math.max(0,p.maxArmor?p.armor/p.maxArmor*100:0)}%`;$('#weaponName').textContent=p.weapon?.name||'무기 없음';$('#ammoText').textContent=p.weapon?`${p.weapon.ammo} / ${p.ammoReserve||0}`:'0 / 0';$('#fireMode').textContent=p.weapon?`${WEAPONS[p.weapon.type].auto?'AUTO':'SEMI'} · T${p.weapon.ammoTier||1}`:'-';const m=Math.floor(snap.timeLeft/60),s=Math.floor(snap.timeLeft%60);$('#raidTimer').textContent=`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;$('#visionHudText').textContent=p.visionLevel;const mapHud=$('#mapHud');if(mapHud)mapHud.textContent=snap.map?.name||roomState?.mapName||'-';$('#killCount').textContent=p.kills;$('#aliveCount').textContent=snap.aliveAI;$('#bagCount').textContent=`${p.inventory.length}/${p.bagCapacity}`;$('#lootValue').textContent=money(p.inventory.reduce((a,b)=>a+(b.value||0),0));$('#grenadeCount').textContent=p.inventory.filter(i=>i.kind==='grenade').length;$('#medCount').textContent=p.inventory.filter(i=>i.kind==='med').length;$('#sprintHud').classList.toggle('hidden',!p.sprinting);renderBag();renderRaidEquipment();renderLoot()}
function renderRaidEquipment(){const slots=['primary','secondary','armor','helmet','backpack'],key=snap.player.weaponSlot+'|'+slots.map(k=>`${k}:${snap.player.gear[k]?.id||''}`).join('|');if(key===hudEqKey)return;hudEqKey=key;const g=$('#raidEquipment');g.innerHTML='';for(const slot of slots){const it=snap.player.gear[slot],d=document.createElement('div'),hotkey=slot==='primary'?'[1] ':slot==='secondary'?'[2] ':'';d.className='raidEqSlot';if(slot===snap.player.weaponSlot&&(slot==='primary'||slot==='secondary')){d.style.borderColor='rgba(116,210,255,.9)';d.style.boxShadow='0 0 0 1px rgba(116,210,255,.25) inset'}d.innerHTML=`<b>${hotkey}${slotNames[slot]}</b><br>${it?itemName(it):'<span class="muted">비어 있음</span>'}`;g.appendChild(d)}}
function renderBag(){const inv=snap.player.inventory,key=snap.player.bagCapacity+'|'+inv.map(it=>`${it.id}:${it.ammo??''}:${it.qty??''}:${it.tier??''}:${it.ammoTier??''}`).join(',');if(key===hudBagKey)return;hudBagKey=key;const g=$('#bagGrid');g.innerHTML='';for(let i=0;i<snap.player.bagCapacity;i++){const it=inv[i],d=document.createElement('div');d.className='bagSlot';if(it){d.innerHTML=`<b>${itemName(it)}</b><small>${itemSub(it)}</small>`;const actions=document.createElement('div');actions.style.display='flex';actions.style.gap='4px';actions.style.flexWrap='wrap';if(['weapon','armor','helmet','backpack'].includes(it.kind)){const b=document.createElement('button');b.textContent='장착';b.onpointerdown=e=>{e.preventDefault();e.stopPropagation();session?.sendAction({type:ACTIONS.EQUIP_BAG,slot:i})};actions.appendChild(b)}const drop=document.createElement('button');drop.textContent='버리기';drop.className='danger';drop.title='이 아이템을 RAID에서 영구 삭제';drop.onpointerdown=e=>{e.preventDefault();e.stopPropagation();session?.sendAction({type:ACTIONS.DISCARD_ITEM,itemId:it.id})};actions.appendChild(drop);d.appendChild(actions)}g.appendChild(d)}}
function canRaidReceive(it,p){if(!it||!p)return false;if(it.kind!=='ammo')return p.inventory.length<p.bagCapacity;return p.inventory.length<p.bagCapacity||p.inventory.some(x=>metaAmmoMatch(x,it)&&(x.qty||0)<AMMO_STACK_MAX)}
function renderLoot(){const p=$('#lootPanel'),c=snap.openContainer;if(!c){if(hudLootKey){hudLootKey='';p.classList.add('hidden')}return}const key=c.id+'|'+c.items.map(i=>`${i.id}:${i.qty??''}:${i.tier??''}`).join(',')+'|'+snap.player.inventory.map(i=>`${i.id}:${i.qty??''}`).join(',')+'/'+snap.player.bagCapacity;if(key===hudLootKey)return;hudLootKey=key;p.classList.remove('hidden');p.innerHTML=`<div style="display:flex;justify-content:space-between"><b>${c.kind==='corpse'?`시체 · ${c.ownerName}`:'보급 상자'}</b><button id="closeLoot">×</button></div><div class="meta" style="margin:5px 0">가까이 있어야 루팅창이 유지됩니다.</div><div id="lootRows"></div>`;$('#closeLoot').onpointerdown=e=>{e.preventDefault();e.stopPropagation();session?.sendAction({type:ACTIONS.CLOSE_CONTAINER})};const rows=p.querySelector('#lootRows');if(!c.items.length)rows.innerHTML='<div class="muted" style="padding:12px">비어 있음</div>';for(const it of c.items){const r=document.createElement('div');r.className='lootRow';r.innerHTML=`<div><b>${itemName(it)}</b><small>${itemSub(it)}</small></div>`;const b=document.createElement('button');b.textContent='획득';b.disabled=!canRaidReceive(it,snap.player);b.onpointerdown=e=>{e.preventDefault();e.stopPropagation();session?.sendAction({type:ACTIONS.LOOT,itemId:it.id,containerId:c.id})};r.appendChild(b);rows.appendChild(r)}}
const progressBox=$('#openProgress'),progressFill=$('#openProgressFill'),progressText=$('#openProgressText');progressFill.style.width='100%';progressFill.style.transformOrigin='left center';progressFill.style.willChange='transform';function renderProgress(now=performance.now()){if(!snap?.player){progressBox.classList.add('hidden');return}const age=Math.min(.12,Math.max(0,(now-lastSnapshotAt)/1000)),show=(pct,text)=>{progressBox.classList.remove('hidden');progressFill.style.transform=`scaleX(${Math.max(0,Math.min(1,pct))})`;progressText.textContent=text};const healBase=snap.player.healTimer||0;if(healBase>0){const heal=Math.max(0,healBase-age),dur=snap.player.healDuration||2;show(1-heal/dur,`치료키트 사용중 · ${heal.toFixed(1)}초`);return}const reloadBase=snap.player.reload||0,weaponType=snap.player.weapon?.type;if(reloadBase>0&&weaponType&&WEAPONS[weaponType]){const reload=Math.max(0,reloadBase-age),dur=WEAPONS[weaponType].reload||1;show(1-reload/dur,`재장전 중 · ${reload.toFixed(1)}초`);return}const q=snap.interaction;if(q){const progress=Math.min(q.duration,q.progress+(keys.has('e')?age:0)),left=Math.max(0,q.duration-progress);show(progress/q.duration,q.kind==='extract'?`탈출 중 ${left.toFixed(1)}초`:`상자 여는 중 ${left.toFixed(1)}초`);return}progressBox.classList.add('hidden')}

function updateRenderActors(dt){for(const [id,r] of renderActors){const d=Math.hypot(r.tx-r.x,r.ty-r.y);if(d>180){r.x=r.tx;r.y=r.ty;r.angle=r.ta;continue}const k=1-Math.exp(-dt*(id===snap?.playerId?34:22));r.x+=(r.tx-r.x)*k;r.y+=(r.ty-r.y)*k;r.angle+=angleDelta(r.ta,r.angle)*k}}
function visualPlayer(){const p=snap?.player,r=p&&renderActors.get(snap.playerId);return p&&r?{...p,x:r.x,y:r.y,angle:r.angle}:p}
function camera(){const p=visualPlayer();if(!p)return{x:0,y:0};const kick=recoilKick,dx=Math.cos(p.angle)*kick,dy=Math.sin(p.angle)*kick;return{x:Math.max(0,Math.min(snap.worldW-canvas.width,p.x-canvas.width/2+dx)),y:Math.max(0,Math.min(snap.worldH-canvas.height,p.y-canvas.height/2+dy))}}
function onScreen(x,y,cam,pad=80){return x>cam.x-pad&&x<cam.x+canvas.width+pad&&y>cam.y-pad&&y<cam.y+canvas.height+pad}
function visionShape(){const p=snap?.player;if(!p)return null;const near=190+p.visionLevel*34,far=near+430+p.visionLevel*58;return{p,near,far,half:1.05}}
function angleDelta(a,b){return Math.atan2(Math.sin(a-b),Math.cos(a-b))}
function pointInVision(x,y){const v=visionShape();if(!v)return false;const dx=x-v.p.x,dy=y-v.p.y,d=Math.hypot(dx,dy);if(d<=v.near)return true;if(d>v.far)return false;return Math.abs(angleDelta(Math.atan2(dy,dx),v.p.angle))<=v.half}
function rectInVision(o){const v=visionShape();if(!v)return false;const px=Math.max(o.x,Math.min(v.p.x,o.x+o.w)),py=Math.max(o.y,Math.min(v.p.y,o.y+o.h));if(Math.hypot(px-v.p.x,py-v.p.y)<=v.near)return true;const pts=[[o.x,o.y],[o.x+o.w,o.y],[o.x,o.y+o.h],[o.x+o.w,o.y+o.h],[o.x+o.w/2,o.y+o.h/2],[px,py]];return pts.some(([x,y])=>pointInVision(x,y))}
let lastDraw=performance.now();function draw(now=performance.now()){requestAnimationFrame(draw);const dt=Math.min(.033,Math.max(.001,(now-lastDraw)/1000));lastDraw=now;recoilKick*=Math.pow(.78,dt*60);shake*=Math.pow(.86,dt*60);hitMarkerT=Math.max(0,hitMarkerT-dt);hurtFlashT=Math.max(0,hurtFlashT-dt);for(const [id,h] of actorHitFlash){h.t-=dt;if(h.t<=0)actorHitFlash.delete(id)}soundMarks.forEach(s=>s.t-=dt);soundMarks=soundMarks.filter(s=>s.t>0);for(const f of fx){f.t-=dt;if(f.vx!=null){f.x+=f.vx*dt;f.y+=f.vy*dt;f.vy+=120*dt}}fx=fx.filter(f=>f.t>0);hitMarkerEl.style.opacity=hitMarkerT>0?'1':'0';hitMarkerEl.style.filter=hitHead?'sepia(1) saturate(4) hue-rotate(5deg)':'none';if(!snap)return;renderProgress(now);updateRenderActors(dt);let cam=camera();if(shake>.2){cam={x:cam.x+(Math.random()-.5)*shake,y:cam.y+(Math.random()-.5)*shake}}ctx.fillStyle='#030506';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.save();ctx.translate(-cam.x,-cam.y);drawGround(cam);drawZones(cam);drawExtracts(cam);drawObstacles(cam);drawDoors(cam);drawCrates(cam);drawCorpses(cam);drawActors(cam);drawGrenades(cam);drawFxWorld(cam);ctx.restore();drawDarkness(cam);ctx.save();ctx.translate(-cam.x,-cam.y);drawBullets(cam);ctx.restore();drawSprintOverlay();drawDamageOverlay();drawSoundIndicators();drawCrosshair();}
